/* ============================================================================
 * hrm-ui · BACK-COMPAT ALIASES
 * ----------------------------------------------------------------------------
 * Cầu nối token cũ ("Twenty": --background/--foreground/--primary/--sidebar-*...)
 * → semantic token mới. Giữ main-layout.scss + màn demo cũ chạy tiếp khi migrate
 * dần. Component MỚI KHÔNG dùng cụm này — dùng semantic/component token trực tiếp.
 * Xoá dần khi đã migrate hết sang token mới.
 * ==========================================================================*/

:root {
  /* Layout cũ (main-layout.scss) */
  --header-height: 40px;                       /* topbar cũ, khác --topbar-height mới */
  --sidebar-width-icon: var(--sidebar-collapsed-width);

  /* Surface / text */
  --background: var(--bg-app);
  --foreground: var(--text-strong);
  --card: var(--bg-surface);
  --card-foreground: var(--text-strong);
  --popover: var(--bg-surface);
  --popover-foreground: var(--text-strong);
  --secondary: var(--bg-surface-subtle);
  --secondary-foreground: var(--text-strong);
  --muted: var(--bg-surface-subtle);
  --muted-foreground: var(--text-sub);
  --accent: var(--bg-surface-muted);           /* neutral bg cũ (#f1f1f1) — section-* override cục bộ khi cần màu */
  --accent-foreground: var(--text-strong);

  /* Primary (Twenty tách sáng/tối — nay 1 primary duy nhất) */
  --primary: var(--primary-base);
  /* --primary-foreground : primitive đã định nghĩa (#FFFFFF) */

  /* Feedback / form */
  --destructive: var(--error-base);
  --border: var(--border-sub);
  --input: var(--border-strong);
  --ring: var(--primary-base);

  /* Charts (chart-5 chưa có token → giữ literal) */
  --chart-1: var(--primary-base);
  --chart-2: var(--success-base);
  --chart-3: var(--warning-base);
  --chart-4: var(--info-base);
  --chart-5: #8E4EC6;

  /* Sidebar cũ → component/semantic token mới */
  --sidebar: var(--sidebar-bg);
  --sidebar-foreground: var(--text-body);
  --sidebar-primary: var(--primary-base);
  --sidebar-primary-foreground: var(--primary-foreground);
  --sidebar-accent: var(--bg-surface-subtle);
  --sidebar-accent-foreground: var(--text-strong);
  --sidebar-border: var(--border-sub);
  --sidebar-ring: var(--primary-base);

  /* Per-section accent (decorative, ngoài spec — giữ nguyên hành vi cũ, dịu 15% về trắng) */
  --section-hr:      color-mix(in oklab, #6366f1 85%, white);
  --section-app:     color-mix(in oklab, #f59e0b 85%, white);
  --section-admin:   color-mix(in oklab, #f43f5e 85%, white);
  --section-master:  color-mix(in oklab, #10b981 85%, white);
  --section-portal:  color-mix(in oklab, #0ea5e9 85%, white);
  --section-neutral: var(--foreground);

  --sidebar-gradient: linear-gradient(180deg, color-mix(in oklab, var(--sidebar) 100%, white 4%) 0%, var(--sidebar) 100%);

  /* Pastel tag palette (ngoài spec — giữ) */
  --tag-green-bg: #def3e4; --tag-green-tx: #1a7f37;
  --tag-blue-bg: #e6edfe; --tag-blue-tx: #3a5ccc;
  --tag-amber-bg: #fbeed3; --tag-amber-tx: #946800;
  --tag-red-bg: #fce9e9; --tag-red-tx: #c3372b;
  --tag-purple-bg: #f1e7fc; --tag-purple-tx: #7d3ac1;
  --tag-sky-bg: #dcf1fb; --tag-sky-tx: #0a6c9c;
  --tag-orange-bg: #fce9d6; --tag-orange-tx: #b45309;
  --tag-pink-bg: #fce4ef; --tag-pink-tx: #c41d7f;
  --tag-gray-bg: #f1f1f1; --tag-gray-tx: #666666;
}

.dark {
  /* Section accent — bản dark sáng/đậm hơn để đọc trên sidebar tối */
  --section-hr:      #818cf8;
  --section-app:     #fbbf24;
  --section-admin:   #fb7185;
  --section-master:  #34d399;
  --section-portal:  #38bdf8;
  --section-neutral: var(--foreground);

  --sidebar-gradient: linear-gradient(180deg, color-mix(in oklab, var(--sidebar) 100%, white 3%) 0%, var(--sidebar) 100%);

  --tag-green-bg: #16341f; --tag-green-tx: #5bd17e;
  --tag-blue-bg: #1c2542; --tag-blue-tx: #8aa3f5;
  --tag-amber-bg: #352a12; --tag-amber-tx: #e9c46a;
  --tag-red-bg: #3a1c1c; --tag-red-tx: #f08a82;
  --tag-purple-bg: #2c1d3f; --tag-purple-tx: #c79af0;
  --tag-sky-bg: #122e3c; --tag-sky-tx: #62c0e8;
  --tag-orange-bg: #34230f; --tag-orange-tx: #e8a45c;
  --tag-pink-bg: #381827; --tag-pink-tx: #f08ac0;
  --tag-gray-bg: #222222; --tag-gray-tx: #b3b3b3;
}
