/* ============================================================================
 * hrm-ui · COMPONENT TOKENS  (Layer 3 — component-specific)
 * ----------------------------------------------------------------------------
 * CHỈ trỏ vào semantic/primitive token. KHÔNG hardcode hex ở đây.
 * Đổi theme tự động theo semantic → không cần override component cho từng theme.
 * ==========================================================================*/

:root {
  /* ------------------------------ Button ------------------------------ */
  --button-primary-bg: var(--primary-base);
  --button-primary-bg-hover: var(--primary-hover);
  --button-primary-bg-pressed: var(--primary-pressed);
  --button-primary-text: var(--primary-foreground);
  --button-primary-border: transparent;
  --button-primary-focus: var(--shadow-focus-primary);

  --button-neutral-bg: var(--bg-inverse);
  --button-neutral-text: var(--text-inverse);
  --button-neutral-bg-hover: color-mix(in oklab, var(--bg-inverse) 88%, var(--bg-surface));
  --button-neutral-focus: var(--shadow-focus-important);

  --button-stroke-bg: var(--bg-surface);
  --button-stroke-text: var(--text-body);
  --button-stroke-border: var(--border-sub);
  --button-stroke-bg-hover: var(--bg-surface-subtle);
  --button-stroke-text-hover: var(--text-strong);
  --button-stroke-border-hover: transparent;

  --button-ghost-bg: transparent;
  --button-ghost-text: var(--text-body);
  --button-ghost-bg-hover: var(--bg-surface-subtle);
  --button-ghost-text-hover: var(--text-strong);

  --button-destructive-bg: var(--error-base);
  --button-destructive-text: var(--error-foreground);
  --button-destructive-bg-hover: color-mix(in oklab, var(--error-base) 88%, black);
  --button-destructive-bg-pressed: color-mix(in oklab, var(--error-base) 76%, black);
  --button-destructive-focus: var(--shadow-focus-error);

  /* ------------------------------ Input ------------------------------ */
  --input-bg: var(--bg-surface);
  --input-bg-hover: var(--bg-surface-subtle);
  --input-bg-disabled: var(--bg-surface-subtle);
  --input-text: var(--text-strong);
  --input-placeholder: var(--text-soft);
  --input-placeholder-hover: var(--text-sub);
  --input-border: var(--border-sub);
  --input-border-hover: var(--border-strong);
  --input-border-focus: var(--border-focus);
  --input-border-error: var(--error-base);
  --input-focus: var(--shadow-focus-primary);
  --input-error-focus: var(--shadow-focus-error);
  --input-height-md: 40px;
  --input-radius: var(--radius-xl);

  /* ----------------------------- Textarea ----------------------------- */
  --textarea-bg: var(--bg-surface);
  --textarea-border: var(--border-sub);
  --textarea-border-focus: var(--border-focus);
  --textarea-min-height: 82px;
  --textarea-padding-x: 12px;
  --textarea-padding-y: 10px;
  --textarea-radius: var(--radius-xl);

  /* ----------------------------- Checkbox ----------------------------- */
  --checkbox-size: 16px;
  --checkbox-radius: var(--radius-xs);
  --checkbox-bg: var(--bg-surface);
  --checkbox-border: var(--border-input); /* WCAG 3:1 — ô trống nhận diện chỉ bằng viền */
  --checkbox-bg-checked: var(--primary-base);
  --checkbox-border-checked: var(--primary-base);
  --checkbox-icon: var(--primary-foreground);
  --checkbox-focus: var(--shadow-focus-primary);

  /* ------------------------------ Radio ------------------------------ */
  --radio-size: 16px;
  --radio-bg: var(--bg-surface);
  --radio-border: var(--border-input); /* WCAG 3:1 — như checkbox */
  --radio-dot: var(--primary-base);
  --radio-focus: var(--shadow-focus-primary);

  /* ------------------------------ Switch ------------------------------ */
  --switch-width: 36px;
  --switch-height: 20px;
  --switch-thumb-size: 16px;
  --switch-bg-off: var(--border-strong);
  --switch-bg-on: var(--primary-base);
  --switch-thumb: #FFFFFF;
  --switch-focus: var(--shadow-focus-primary);

  /* ------------------------------ Sidebar ------------------------------ */
  --sidebar-bg: var(--bg-surface);
  --sidebar-border: var(--border-sub);
  /* --sidebar-width / --sidebar-collapsed-width : primitive (layout) */
  --sidebar-item-height: 40px;
  --sidebar-item-radius: var(--radius-lg);
  --sidebar-item-text: var(--text-body);
  --sidebar-item-icon: var(--text-sub);
  --sidebar-item-hover-bg: var(--bg-surface-subtle);
  --sidebar-item-hover-text: var(--text-strong);
  --sidebar-item-selected-bg: var(--primary-bg-subtle);
  --sidebar-item-selected-text-light: var(--primary-base);
  --sidebar-item-selected-text-dark: var(--text-strong);
  --sidebar-item-selected-icon: var(--primary-base);
  --sidebar-item-selected-indicator: var(--primary-base);

  /* ------------------------------ Topbar ------------------------------ */
  --topbar-bg: var(--bg-surface);
  --topbar-border: var(--border-sub);
  --topbar-text: var(--text-body);
  --topbar-icon: var(--text-sub);
  --topbar-action-hover-bg: var(--bg-surface-subtle);

  /* ------------------------------ Table ------------------------------ */
  --table-bg: var(--bg-surface);
  --table-header-bg: var(--bg-surface-subtle);
  --table-border: var(--border-sub);
  --table-row-bg: var(--bg-surface);
  --table-row-hover-bg: var(--bg-surface-subtle);
  --table-row-selected-bg: var(--primary-bg-subtle);
  --table-header-text: var(--text-sub);
  --table-body-text: var(--text-body);
  --table-strong-text: var(--text-strong);
  --table-row-height-compact: 40px;
  --table-row-height-standard: 48px;
  --table-row-height-comfortable: 56px;

  /* ------------------------------- Tabs ------------------------------- */
  --tab-text: var(--text-sub);
  --tab-text-hover: var(--text-strong);
  --tab-text-active-light: var(--primary-base);
  --tab-text-active-dark: var(--text-strong);
  --tab-border-active: var(--primary-base);
  --tab-bg-hover: var(--bg-surface-subtle);
  --tab-bg-active: var(--bg-surface-subtle);

  /* ------------------------------ Badge ------------------------------ */
  --badge-radius: var(--radius-full);
  --badge-padding-x: 8px;
  --badge-height-sm: 20px;
  --badge-height-md: 24px;
  --badge-text: var(--text-body);

  --badge-primary-bg: var(--primary-bg-subtle);
  --badge-primary-text-light: var(--primary-base);
  --badge-primary-text-dark: var(--text-strong);
  --badge-primary-border: var(--primary-border);

  --badge-success-bg-light: var(--success-bg);
  --badge-success-bg-dark: var(--success-bg-dark);
  --badge-success-text-light: var(--success-text);
  --badge-success-text-dark: var(--success-text-dark);
  --badge-success-border-light: var(--success-border);
  --badge-success-border-dark: var(--success-border-dark);

  --badge-warning-bg-light: var(--warning-bg);
  --badge-warning-bg-dark: var(--warning-bg-dark);
  --badge-warning-text-light: var(--warning-text);
  --badge-warning-text-dark: var(--warning-text-dark);
  --badge-warning-border-light: var(--warning-border);
  --badge-warning-border-dark: var(--warning-border-dark);

  --badge-error-bg-light: var(--error-bg);
  --badge-error-bg-dark: var(--error-bg-dark);
  --badge-error-text-light: var(--error-text);
  --badge-error-text-dark: var(--error-text-dark);
  --badge-error-border-light: var(--error-border);
  --badge-error-border-dark: var(--error-border-dark);

  /* ------------------------------- Card ------------------------------- */
  --card-bg: var(--bg-surface);
  --card-border: var(--border-sub);
  --card-radius: var(--radius-2xl);
  --card-padding-sm: 16px;
  --card-padding-md: 20px;
  --card-padding-lg: 24px;
  --card-shadow: var(--shadow-regular-xs);

  /* -------------------------- Dropdown / Popover -------------------------- */
  --popover-bg: var(--bg-surface);
  --popover-border: var(--border-sub);
  --popover-radius: var(--radius-2xl);
  --popover-padding: 8px;
  --popover-shadow: var(--shadow-regular-md);
  --popover-z-index: var(--z-popover);

  /* ------------------------------ Modal ------------------------------ */
  --modal-bg: var(--bg-surface);
  --modal-border: var(--border-sub);
  --modal-radius: var(--radius-3xl);
  --modal-shadow: var(--shadow-regular-lg);
  --modal-overlay: var(--overlay);
  --modal-z-index: var(--z-modal);

  /* ------------------------------ Drawer ------------------------------ */
  --drawer-bg: var(--bg-surface);
  --drawer-border: var(--border-sub);
  --drawer-shadow: var(--shadow-regular-lg);
  --drawer-overlay: var(--overlay);
  --drawer-z-index: var(--z-drawer);

  /* ------------------------------ Toast ------------------------------ */
  --toast-bg: var(--bg-surface);
  --toast-border: var(--border-sub);
  --toast-radius: var(--radius-2xl);
  --toast-shadow: var(--shadow-regular-md);
  --toast-z-index: var(--z-toast);

  /* ----------------------------- Tooltip ----------------------------- */
  --tooltip-bg: var(--bg-inverse);
  --tooltip-text: var(--text-inverse);
  --tooltip-radius: var(--radius-md);
  --tooltip-padding-x: 8px;
  --tooltip-padding-y: 4px;
  --tooltip-font-size: var(--text-label-xs-font-size);
  --tooltip-z-index: var(--z-tooltip);

  /* ------------------------ Table (hrm-grid) ------------------------- */
  /* Mật độ mặc định = balanced. Đổi GLOBAL qua html[data-density] (config app);
     đổi CỤC BỘ qua input [density] của hrm-grid (override thắng global). */
  --table-cell-pad: 8px 12px;
  --table-font-size: var(--fs-13);
  /* Chiều cao tối thiểu hàng HEADER — cố định mọi mật độ (không co theo padding). */
  --table-header-height: 36px;
}

/* Mật độ toàn cục (Astryx density) — config app set data-density trên <html>, mọi bảng tự đổi. */
html[data-density='compact'] { --table-cell-pad: 4px 10px; --table-font-size: var(--fs-12); }
html[data-density='spacious'] { --table-cell-pad: 14px 16px; --table-font-size: var(--fs-14); }
