/* ============================================================================
 * hrm-ui · PRIMITIVE TOKENS  (Layer 1 — raw values, theme-agnostic)
 * ----------------------------------------------------------------------------
 * Không dùng trực tiếp trong component. Component dùng semantic/component token.
 * Ngoại lệ với spec: size nhỏ nhất = 12px (rule dự án), subheading-2xs bump 11→12.
 * ==========================================================================*/

:root {
  /* ---------- Font ----------
   * --font-sans = font đang dùng (default Roboto). Config/tenant set lại --font-sans
   * = 1 stack dưới. Roboto = default ship (rule dự án). Font Việt tốt: Roboto,
   * Be Vietnam Pro, Inter. SF Pro = system-only (license Apple, không @import được —
   * chỉ hiện trên máy Apple, nơi khác fallback Roboto). */
  --font-roboto: 'Roboto', Arial, sans-serif;
  --font-inter: 'Inter', 'Roboto', Arial, sans-serif;
  --font-bevietnam: 'Be Vietnam Pro', 'Roboto', Arial, sans-serif;
  --font-sfpro: -apple-system, BlinkMacSystemFont, 'SF Pro Text', 'SF Pro', 'Roboto', Arial, sans-serif;

  --font-sans: var(--font-roboto);
  --font-mono: 'Roboto Mono', 'Roboto', ui-monospace, monospace; /* dùng tabular-nums cho số */

  --font-regular: 400;
  --font-medium: 500;
  --font-semibold: 600;
  --font-bold: 700;

  /* ---------- Primary (1 màu duy nhất, giống nhau Light/Dark) ---------- */
  --primary-base: #2267E8;
  --primary-foreground: #FFFFFF;

  /* Alpha derive từ --primary-base → đổi brand color tự lan. */
  --primary-alpha-32: color-mix(in srgb, var(--primary-base) 32%, transparent);
  --primary-alpha-24: color-mix(in srgb, var(--primary-base) 24%, transparent);
  --primary-alpha-16: color-mix(in srgb, var(--primary-base) 16%, transparent);
  --primary-alpha-12: color-mix(in srgb, var(--primary-base) 12%, transparent);
  --primary-alpha-10: color-mix(in srgb, var(--primary-base) 10%, transparent);
  --primary-alpha-08: color-mix(in srgb, var(--primary-base) 8%, transparent);

  /* ---------- Neutral · Slate (default) ---------- */
  --slate-0: #FFFFFF;
  --slate-50: #F5F7FA;
  --slate-100: #F2F5F8;
  --slate-200: #E1E4EA;
  --slate-300: #CACFD8;
  --slate-400: #99A0AE;
  --slate-500: #717784;
  --slate-600: #525866;
  --slate-700: #2B303B;
  --slate-800: #222530;
  --slate-900: #181B25;
  --slate-950: #0E121B;

  /* ---------- Neutral · Gray (optional Classic — KHÔNG mix với Slate) ---------- */
  --gray-0: #FFFFFF;
  --gray-50: #F7F7F7;
  --gray-100: #F5F5F5;
  --gray-200: #EBEBEB;
  --gray-300: #D1D1D1;
  --gray-400: #A3A3A3;
  --gray-500: #7B7B7B;
  --gray-600: #5C5C5C;
  --gray-700: #333333;
  --gray-800: #262626;
  --gray-900: #1C1C1C;
  --gray-950: #171717;

  /* neutral = slate mặc định. Classic theme override cụm này thành gray-*. */
  --neutral-0: var(--slate-0);
  --neutral-50: var(--slate-50);
  --neutral-100: var(--slate-100);
  --neutral-200: var(--slate-200);
  --neutral-300: var(--slate-300);
  --neutral-400: var(--slate-400);
  --neutral-500: var(--slate-500);
  --neutral-600: var(--slate-600);
  --neutral-700: var(--slate-700);
  --neutral-800: var(--slate-800);
  --neutral-900: var(--slate-900);
  --neutral-950: var(--slate-950);

  /* ---------- Accent / Status hue ramps (full 50→950) ----------
   * Mỗi status = 1 hue, mỗi hue 1 thang đầy đủ (giống Slate). Base neo theo giá trị
   * nền tảng đã dùng; bậc phụ theo curve Tailwind (perceptually đều). Semantic status
   * token phân bổ xuống từ đây: base=600 · text=800 · border=200 · bg=50 · dark text=300.
   * Map: information→blue · success→green · warning→amber · error→red · away→yellow
   *      feature→purple · stable→teal · highlighted→cyan · social→pink. */
  --blue-50:#EFF6FF; --blue-100:#D9E8FE; --blue-200:#BAD6FD; --blue-300:#8BBAFB; --blue-400:#5695F7; --blue-500:#2F76EE; --blue-600:#2267E8; --blue-700:#1B4FBE; --blue-800:#1C4499; --blue-900:#1C3C7A; --blue-950:#15264A;
  --green-50:#F0FDF4; --green-100:#DCFCE7; --green-200:#BBF7D0; --green-300:#86EFAC; --green-400:#4ADE80; --green-500:#22C55E; --green-600:#16A34A; --green-700:#15803D; --green-800:#166534; --green-900:#14532D; --green-950:#052E16;
  --amber-50:#FFFBEB; --amber-100:#FEF3C7; --amber-200:#FDE68A; --amber-300:#FCD34D; --amber-400:#FBBF24; --amber-500:#F59E0B; --amber-600:#D97706; --amber-700:#B45309; --amber-800:#92400E; --amber-900:#78350F; --amber-950:#451A03;
  --red-50:#FEF2F2; --red-100:#FEE2E2; --red-200:#FECACA; --red-300:#FCA5A5; --red-400:#F87171; --red-500:#EF4444; --red-600:#DC2626; --red-700:#B91C1C; --red-800:#991B1B; --red-900:#7F1D1D; --red-950:#450A0A;
  --yellow-50:#FEFCE8; --yellow-100:#FEF9C3; --yellow-200:#FEF08A; --yellow-300:#FDE047; --yellow-400:#FACC15; --yellow-500:#EAB308; --yellow-600:#CA8A04; --yellow-700:#A16207; --yellow-800:#854D0E; --yellow-900:#713F12; --yellow-950:#422006;
  --purple-50:#F5F3FF; --purple-100:#EDE9FE; --purple-200:#DDD6FE; --purple-300:#C4B5FD; --purple-400:#A78BFA; --purple-500:#8B5CF6; --purple-600:#7C3AED; --purple-700:#6D28D9; --purple-800:#5B21B6; --purple-900:#4C1D95; --purple-950:#2E1065;
  --teal-50:#F0FDFA; --teal-100:#CCFBF1; --teal-200:#99F6E4; --teal-300:#5EEAD4; --teal-400:#2DD4BF; --teal-500:#14B8A6; --teal-600:#0D9488; --teal-700:#0F766E; --teal-800:#115E59; --teal-900:#134E4A; --teal-950:#042F2E;
  --cyan-50:#ECFEFF; --cyan-100:#CFFAFE; --cyan-200:#A5F3FC; --cyan-300:#67E8F9; --cyan-400:#22D3EE; --cyan-500:#06B6D4; --cyan-600:#0891B2; --cyan-700:#0E7490; --cyan-800:#155E75; --cyan-900:#164E63; --cyan-950:#083344;
  --pink-50:#FDF2F8; --pink-100:#FCE7F3; --pink-200:#FBCFE8; --pink-300:#F9A8D4; --pink-400:#F472B6; --pink-500:#EC4899; --pink-600:#DB2C97; --pink-700:#BE185D; --pink-800:#9D174D; --pink-900:#831843; --pink-950:#500724;

  /* ---------- State colors (phân bổ từ ramp trên — light + dark variant) ---------- */
  --success-base: var(--green-600);
  --success-foreground: #FFFFFF;
  --success-text-light: var(--green-800);
  --success-text-dark: var(--green-300);
  --success-bg-light: var(--green-50);
  --success-bg-dark: color-mix(in srgb, var(--green-500) 16%, transparent);
  --success-border-light: var(--green-200);
  --success-border-dark: color-mix(in srgb, var(--green-300) 32%, transparent);

  --warning-base: var(--amber-600);
  --warning-foreground: #0A1317; /* WCAG: chữ trắng trên cam chỉ 3.19 (fail) → chữ tối */
  --warning-text-light: var(--amber-800);
  --warning-text-dark: var(--amber-300);
  --warning-bg-light: var(--amber-50);
  --warning-bg-dark: color-mix(in srgb, var(--amber-500) 16%, transparent);
  --warning-border-light: var(--amber-200);
  --warning-border-dark: color-mix(in srgb, var(--amber-300) 32%, transparent);

  --error-base: var(--red-600);
  --error-foreground: #FFFFFF;
  --error-text-light: var(--red-800);
  --error-text-dark: var(--red-300);
  --error-bg-light: var(--red-50);
  --error-bg-dark: color-mix(in srgb, var(--red-500) 16%, transparent);
  --error-border-light: var(--red-200);
  --error-border-dark: color-mix(in srgb, var(--red-300) 32%, transparent);

  --info-base: var(--blue-600);
  --info-foreground: #FFFFFF;
  --info-text-light: var(--blue-600);
  --info-text-dark: var(--blue-300);
  --info-bg-light: color-mix(in srgb, var(--blue-600) 10%, transparent);
  --info-bg-dark: color-mix(in srgb, var(--blue-600) 16%, transparent);
  --info-border-light: color-mix(in srgb, var(--blue-600) 24%, transparent);
  --info-border-dark: color-mix(in srgb, var(--blue-600) 32%, transparent);

  /* ---------- State · tier phụ (dark / muted / on) ----------
   * -dark  = hover/pressed cho nút solid (đậm hơn base).
   * -on    = màu chữ/icon TRÊN nút solid. WCAG: warning/away nền sáng → chữ TỐI.
   * -muted = nền/ring mờ (alpha) cho alert/badge nhẹ. */
  --success-dark: var(--green-700);
  --success-on: #FFFFFF;
  --success-muted-light: color-mix(in srgb, var(--green-600) 12%, transparent);
  --success-muted-dark:  color-mix(in srgb, var(--green-600) 20%, transparent);

  --warning-dark: var(--amber-700);
  --warning-on: #0A1317;   /* chữ trắng trên cam = 3.19 (fail) → tối = 5.89 (AA) */
  --warning-muted-light: color-mix(in srgb, var(--amber-600) 12%, transparent);
  --warning-muted-dark:  color-mix(in srgb, var(--amber-600) 20%, transparent);

  --error-dark: var(--red-700);
  --error-on: #FFFFFF;
  --error-muted-light: color-mix(in srgb, var(--red-600) 12%, transparent);
  --error-muted-dark:  color-mix(in srgb, var(--red-600) 20%, transparent);

  --info-dark: var(--blue-700);
  --info-on: #FFFFFF;
  --info-muted-light: color-mix(in srgb, var(--blue-600) 12%, transparent);
  --info-muted-dark:  color-mix(in srgb, var(--blue-600) 20%, transparent);

  /* ---------- Away (status vàng — presence / chấm công) ----------
   * online=success · away=away · busy=error · offline=neutral-400. */
  --away-base: var(--yellow-500);
  --away-dark: var(--yellow-600);
  --away-on: #0A1317;      /* chữ trắng trên vàng = 1.92 (fail nặng) → tối = 9.79 (AAA) */
  --away-text-light: var(--yellow-800);
  --away-text-dark:  var(--yellow-300);
  --away-bg-light: var(--yellow-50);
  --away-bg-dark:  color-mix(in srgb, var(--yellow-500) 16%, transparent);
  --away-border-light: var(--yellow-200);
  --away-border-dark:  color-mix(in srgb, var(--yellow-300) 32%, transparent);

  /* ---------- Accent status phụ (feature / stable / highlighted / social) ----------
   * Cùng khuôn phân bổ: base=600 · text=800/dark 300 · bg=50/dark alpha16 · border=200/dark alpha32.
   * feature→purple (mới/nổi bật) · stable→teal (ổn định) · highlighted→cyan (được nhấn) · social→pink. */
  --feature-base: var(--purple-600); --feature-on: #FFFFFF;
  --feature-text-light: var(--purple-800); --feature-text-dark: var(--purple-300);
  --feature-bg-light: var(--purple-50);    --feature-bg-dark: color-mix(in srgb, var(--purple-500) 16%, transparent);
  --feature-border-light: var(--purple-200); --feature-border-dark: color-mix(in srgb, var(--purple-300) 32%, transparent);

  --stable-base: var(--teal-600); --stable-on: #FFFFFF;
  --stable-text-light: var(--teal-800); --stable-text-dark: var(--teal-300);
  --stable-bg-light: var(--teal-50);    --stable-bg-dark: color-mix(in srgb, var(--teal-500) 16%, transparent);
  --stable-border-light: var(--teal-200); --stable-border-dark: color-mix(in srgb, var(--teal-300) 32%, transparent);

  --highlighted-base: var(--cyan-600); --highlighted-on: #FFFFFF;
  --highlighted-text-light: var(--cyan-800); --highlighted-text-dark: var(--cyan-300);
  --highlighted-bg-light: var(--cyan-50);    --highlighted-bg-dark: color-mix(in srgb, var(--cyan-500) 16%, transparent);
  --highlighted-border-light: var(--cyan-200); --highlighted-border-dark: color-mix(in srgb, var(--cyan-300) 32%, transparent);

  --social-base: var(--pink-600); --social-on: #FFFFFF;
  --social-text-light: var(--pink-800); --social-text-dark: var(--pink-300);
  --social-bg-light: var(--pink-50);    --social-bg-dark: color-mix(in srgb, var(--pink-500) 16%, transparent);
  --social-border-light: var(--pink-200); --social-border-dark: color-mix(in srgb, var(--pink-300) 32%, transparent);

  /* ---------- Static (KHÔNG đổi theo theme — dùng khi cần cố định) ---------- */
  --static-white: #FFFFFF;
  --static-black: #0A1317;
  --on-dark: #FFFFFF;   /* chữ/icon trên nền tối hoặc màu đặc */
  --on-light: #0A1317;  /* chữ/icon trên nền sáng */

  /* ---------- Neutral alpha (overlay/hover/scrim trên nền neutral) ---------- */
  --neutral-alpha-24: color-mix(in srgb, var(--neutral-950) 24%, transparent);
  --neutral-alpha-16: color-mix(in srgb, var(--neutral-950) 16%, transparent);
  --neutral-alpha-10: color-mix(in srgb, var(--neutral-950) 10%, transparent);

  /* ---------- Tag / Label hues (raw · role-based, KHÔNG full ramp) ----------
   * base = màu nhận diện; fg-light/fg-dark = chữ theo theme (đều AAA cả Slate+Gray).
   * bg + border derive bằng alpha ở semantic.css → tự bám mọi nền. Dùng CÓ legend. */
  --hue-gray-base:   #64748B; --hue-gray-fg-light:   #334155; --hue-gray-fg-dark:   #CBD5E1;
  --hue-blue-base:   #0171E3; --hue-blue-fg-light:   #04328F; --hue-blue-fg-dark:   #AFD7FF;
  --hue-cyan-base:   #0891B2; --hue-cyan-fg-light:   #014975; --hue-cyan-fg-dark:   #A1EEF9;
  --hue-green-base:  #16A34A; --hue-green-fg-light:  #09441F; --hue-green-fg-dark:  #A5F690;
  --hue-yellow-base: #EAB308; --hue-yellow-fg-light: #713F12; --hue-yellow-fg-dark: #FDE047;
  --hue-orange-base: #EA6E00; --hue-orange-fg-light: #6B2203; --hue-orange-fg-dark: #FDB876;
  --hue-red-base:    #E3193B; --hue-red-fg-light:    #7B0210; --hue-red-fg-dark:    #FFB2B8;
  --hue-pink-base:   #DB2C97; --hue-pink-fg-light:   #650053; --hue-pink-fg-dark:   #FEADE3;
  --hue-purple-base: #7C3AED; --hue-purple-fg-light: #3E0697; --hue-purple-fg-dark: #C4B5FD;
  --hue-teal-base:   #0D9488; --hue-teal-fg-light:   #083943; --hue-teal-fg-dark:   #40DCCD;

  /* ---------- Data-viz ----------
   * categorical = thứ tự cố định (chống trùng khi nhiều series); seq = heatmap 5 bậc.
   * Modern/tech: neo bậc 500 của hue ramp (điện/sáng hơn base 600), thứ tự đẩy
   * violet·teal·cyan·magenta lên trước để 2 series kề nhau tương phản mạnh. Vì trỏ
   * ramp nên đổi brand/neutral vẫn tự bám. */
  --data-1: var(--purple-400); --data-2: var(--cyan-400); --data-3: var(--blue-400); --data-4: var(--teal-400); --data-5: var(--pink-400);
  --data-6: var(--green-400); --data-7: var(--amber-400); --data-8: var(--blue-600); --data-9: var(--red-400); --data-10: var(--yellow-400);
  --data-neutral: var(--slate-400);
  --seq-blue-1:#DBECFF; --seq-blue-2:#78BEFF; --seq-blue-3:#2694FE; --seq-blue-4:#004CBC; --seq-blue-5:#02165E;
  --seq-green-1:#D6FEE4; --seq-green-2:#8EF7AA; --seq-green-3:#24BB5E; --seq-green-4:#138546; --seq-green-5:#0B603D;
  --seq-red-1:#FEE4E6; --seq-red-2:#FFB2B8; --seq-red-3:#FB7D87; --seq-red-4:#D31130; --seq-red-5:#9D0519;

  /* ---------- Spacing (4px base) ---------- */
  --space-0: 0px;
  --space-0-5: 2px;
  --space-1: 4px;
  --space-1-5: 6px;
  --space-2: 8px;
  --space-2-5: 10px;
  --space-3: 12px;
  --space-3-5: 14px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-7: 28px;
  --space-8: 32px;
  --space-9: 36px;
  --space-10: 40px;
  --space-11: 44px;
  --space-12: 48px;
  --space-14: 56px;
  --space-16: 64px;
  --space-20: 80px;
  --space-24: 96px;

  /* ---------- Size · Icon ---------- */
  --icon-xs: 12px;
  --icon-sm: 16px;
  --icon-md: 20px;
  --icon-lg: 24px;
  --icon-xl: 28px;

  /* ---------- Size · Control height ---------- */
  --control-height-2xs: 28px;
  --control-height-xs: 32px;
  --control-height-sm: 36px;
  --control-height-md: 40px;
  --control-height-lg: 44px;
  --control-height-xl: 48px;

  /* ---------- Size · Avatar ---------- */
  --avatar-xs: 20px;
  --avatar-sm: 24px;
  --avatar-md: 32px;
  --avatar-lg: 40px;
  --avatar-xl: 48px;
  --avatar-2xl: 56px;

  /* ---------- Layout ---------- */
  --sidebar-width: 280px;
  --sidebar-collapsed-width: 72px;
  --topbar-height: 64px;
  --content-max-width: 1440px;

  /* ---------- Radius ----------
   * Scale qua --radius-scale (default 1). Config đổi 1 biến → cả thang radius đổi
   * (sharp 0.5 / default 1 / rounded 1.6...). none/full cố định (không scale). */
  --radius-scale: 1;
  --radius-none: 0px;
  --radius-2xs: calc(2px * var(--radius-scale));
  --radius-xs: calc(4px * var(--radius-scale));
  --radius-sm: calc(6px * var(--radius-scale));
  --radius-md: calc(8px * var(--radius-scale));
  --radius-lg: calc(10px * var(--radius-scale));
  --radius-xl: calc(12px * var(--radius-scale));
  --radius-2xl: calc(16px * var(--radius-scale));
  --radius-3xl: calc(20px * var(--radius-scale));
  --radius-4xl: calc(24px * var(--radius-scale));
  --radius-5xl: calc(28px * var(--radius-scale));
  --radius-full: 999px;

  /* ---------- Font size ----------
   * Scale qua --font-scale (default 1). Config đổi 1 biến → CHỮ toàn hệ thống đổi
   * (nhỏ 0.875 / vừa 1 / lớn 1.125), khoảng cách & bo góc KHÔNG đổi (mật độ do
   * --density, bo góc do --radius-scale lo). Tên token = số px gốc ở scale 1 →
   * đọc là biết cỡ, migrate 1:1 từ hard-code cũ, không lệch pixel khi scale = 1. */
  --font-scale: 1;
  --fs-10: calc(10px * var(--font-scale));
  --fs-11: calc(11px * var(--font-scale));
  --fs-12: calc(12px * var(--font-scale));
  --fs-13: calc(13px * var(--font-scale));
  --fs-14: calc(14px * var(--font-scale));
  --fs-15: calc(15px * var(--font-scale));
  --fs-16: calc(16px * var(--font-scale));
  --fs-18: calc(18px * var(--font-scale));
  --fs-19: calc(19px * var(--font-scale));
  --fs-20: calc(20px * var(--font-scale));
  --fs-22: calc(22px * var(--font-scale));
  --fs-24: calc(24px * var(--font-scale));
  --fs-26: calc(26px * var(--font-scale));
  --fs-28: calc(28px * var(--font-scale));
  --fs-30: calc(30px * var(--font-scale));
  --fs-32: calc(32px * var(--font-scale));

  /* ---------- Border width ---------- */
  --border-width-none: 0px;
  --border-width-sm: 1px;
  --border-width-md: 2px;

  /* ---------- Shadow · Light (dark override ở semantic.css) ---------- */
  --shadow-none: none;
  --shadow-regular-xs: 0 1px 2px rgb(14 18 27 / 0.06);
  --shadow-regular-sm: 0 2px 4px rgb(14 18 27 / 0.08);
  --shadow-regular-md: 0 8px 24px rgb(14 18 27 / 0.10);
  --shadow-regular-lg: 0 16px 40px rgb(14 18 27 / 0.14);

  /* Focus shadow — trỏ vào --primary-focus-ring (semantic, đổi theo theme) */
  --shadow-focus-primary: 0 0 0 3px var(--primary-focus-ring);
  --shadow-focus-important: 0 0 0 3px rgb(14 18 27 / 0.12);
  --shadow-focus-error: 0 0 0 3px rgb(220 38 38 / 0.24);

  /* ---------- Motion ---------- */
  --duration-instant: 0ms;
  --duration-fast: 100ms;
  --duration-normal: 200ms;
  --duration-slow: 300ms;
  --duration-slower: 500ms;

  --ease-linear: linear;
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in: cubic-bezier(0.32, 0, 0.67, 0);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);

  /* ---------- Z-index ---------- */
  --z-base: 0;
  --z-raised: 10;
  --z-sticky: 100;
  --z-header: 200;
  --z-sidebar: 300;
  --z-dropdown: 500;
  --z-popover: 600;
  --z-drawer: 700;
  --z-modal: 800;
  --z-toast: 900;
  --z-tooltip: 1000;

  /* ---------- Breakpoints (tham chiếu, dùng trong media query qua giá trị) ---------- */
  --breakpoint-sm: 640px;
  --breakpoint-md: 768px;
  --breakpoint-lg: 1024px;
  --breakpoint-xl: 1280px;
  --breakpoint-2xl: 1536px;

  /* ======================= Typography scale ======================= */
  /* Title */
  --text-title-h1-font-size: calc(56px * var(--font-scale));
  --text-title-h1-line-height: 64px;
  --text-title-h1-font-weight: 500;
  --text-title-h1-letter-spacing: -0.01em;

  --text-title-h2-font-size: calc(48px * var(--font-scale));
  --text-title-h2-line-height: 56px;
  --text-title-h2-font-weight: 500;
  --text-title-h2-letter-spacing: -0.01em;

  --text-title-h3-font-size: calc(40px * var(--font-scale));
  --text-title-h3-line-height: 48px;
  --text-title-h3-font-weight: 500;
  --text-title-h3-letter-spacing: -0.01em;

  --text-title-h4-font-size: calc(32px * var(--font-scale));
  --text-title-h4-line-height: 40px;
  --text-title-h4-font-weight: 500;
  --text-title-h4-letter-spacing: -0.005em;

  --text-title-h5-font-size: calc(24px * var(--font-scale));
  --text-title-h5-line-height: 32px;
  --text-title-h5-font-weight: 500;
  --text-title-h5-letter-spacing: 0em;

  --text-title-h6-font-size: calc(20px * var(--font-scale));
  --text-title-h6-line-height: 28px;
  --text-title-h6-font-weight: 500;
  --text-title-h6-letter-spacing: 0em;

  /* Label */
  --text-label-xl-font-size: calc(24px * var(--font-scale));
  --text-label-xl-line-height: 32px;
  --text-label-xl-font-weight: 500;
  --text-label-xl-letter-spacing: -0.015em;

  --text-label-lg-font-size: calc(18px * var(--font-scale));
  --text-label-lg-line-height: 24px;
  --text-label-lg-font-weight: 500;
  --text-label-lg-letter-spacing: -0.015em;

  --text-label-md-font-size: calc(16px * var(--font-scale));
  --text-label-md-line-height: 24px;
  --text-label-md-font-weight: 500;
  --text-label-md-letter-spacing: -0.011em;

  --text-label-sm-font-size: calc(14px * var(--font-scale));
  --text-label-sm-line-height: 20px;
  --text-label-sm-font-weight: 500;
  --text-label-sm-letter-spacing: -0.006em;

  --text-label-xs-font-size: calc(12px * var(--font-scale));
  --text-label-xs-line-height: 16px;
  --text-label-xs-font-weight: 500;
  --text-label-xs-letter-spacing: 0em;

  /* Paragraph */
  --text-paragraph-xl-font-size: calc(24px * var(--font-scale));
  --text-paragraph-xl-line-height: 32px;
  --text-paragraph-xl-font-weight: 400;
  --text-paragraph-xl-letter-spacing: -0.015em;

  --text-paragraph-lg-font-size: calc(18px * var(--font-scale));
  --text-paragraph-lg-line-height: 24px;
  --text-paragraph-lg-font-weight: 400;
  --text-paragraph-lg-letter-spacing: -0.015em;

  --text-paragraph-md-font-size: calc(16px * var(--font-scale));
  --text-paragraph-md-line-height: 24px;
  --text-paragraph-md-font-weight: 400;
  --text-paragraph-md-letter-spacing: -0.011em;

  --text-paragraph-sm-font-size: calc(14px * var(--font-scale));
  --text-paragraph-sm-line-height: 20px;
  --text-paragraph-sm-font-weight: 400;
  --text-paragraph-sm-letter-spacing: -0.006em;

  --text-paragraph-xs-font-size: calc(12px * var(--font-scale));
  --text-paragraph-xs-line-height: 16px;
  --text-paragraph-xs-font-weight: 400;
  --text-paragraph-xs-letter-spacing: 0em;

  /* Subheading (uppercase) */
  --text-subheading-md-font-size: calc(16px * var(--font-scale));
  --text-subheading-md-line-height: 24px;
  --text-subheading-md-font-weight: 500;
  --text-subheading-md-letter-spacing: 0.06em;
  --text-subheading-md-text-transform: uppercase;

  --text-subheading-sm-font-size: calc(14px * var(--font-scale));
  --text-subheading-sm-line-height: 20px;
  --text-subheading-sm-font-weight: 500;
  --text-subheading-sm-letter-spacing: 0.06em;
  --text-subheading-sm-text-transform: uppercase;

  --text-subheading-xs-font-size: calc(12px * var(--font-scale));
  --text-subheading-xs-line-height: 16px;
  --text-subheading-xs-font-weight: 500;
  --text-subheading-xs-letter-spacing: 0.04em;
  --text-subheading-xs-text-transform: uppercase;

  /* 2xs: spec 11px → bump 12px (rule dự án: size nhỏ nhất 12px) */
  --text-subheading-2xs-font-size: calc(12px * var(--font-scale));
  --text-subheading-2xs-line-height: 16px;
  --text-subheading-2xs-font-weight: 500;
  --text-subheading-2xs-letter-spacing: 0.02em;
  --text-subheading-2xs-text-transform: uppercase;

  /* Document */
  --text-doc-label-font-size: calc(18px * var(--font-scale));
  --text-doc-label-line-height: 32px;
  --text-doc-label-font-weight: 500;
  --text-doc-label-letter-spacing: -0.015em;

  --text-doc-paragraph-font-size: calc(18px * var(--font-scale));
  --text-doc-paragraph-line-height: 32px;
  --text-doc-paragraph-font-weight: 400;
  --text-doc-paragraph-letter-spacing: -0.015em;
}

/* ---------- Neutral ramp switch ----------
 * Default = Slate (map ở :root trên). Đặt data-neutral="gray" trên <html> để đổi
 * TOÀN BỘ neutral sang Gray classic — vì semantic bg/text/border trỏ --neutral-*
 * nên đổi cả Light + Dark cùng lúc. KHÔNG mix Slate + Gray trong 1 theme. */
[data-neutral='gray'] {
  --neutral-0: var(--gray-0);
  --neutral-50: var(--gray-50);
  --neutral-100: var(--gray-100);
  --neutral-200: var(--gray-200);
  --neutral-300: var(--gray-300);
  --neutral-400: var(--gray-400);
  --neutral-500: var(--gray-500);
  --neutral-600: var(--gray-600);
  --neutral-700: var(--gray-700);
  --neutral-800: var(--gray-800);
  --neutral-900: var(--gray-900);
  --neutral-950: var(--gray-950);
}
