/* Tailwind v4 utilities + base — PRECOMPILED (static) to tw.generated.css.
   Regenerate with: node apps/ds-demo/build-tailwind.mjs  (nx target: ds-demo:tw). */
@import './tw.generated.css';

/* ng-zorro theme CSS-variable (base) — phải đứng TRƯỚC bridge để bridge override. */
@import 'ng-zorro-antd/ng-zorro-antd.variable.min.css';

/* ===== hrm-ui design token foundation (source of truth, vendored) ===== */
@import '../../../libs/hrm-ui/styles/index.css';

/* Bridge ng-zorro → design token (map .ant-* sang semantic token → tự Light/Dark/brand). */
@import '../../../libs/hrm-ui/styles/ng-zorro-bridge.css';

/* ===== Component helper classes (Roboto uppercase label, pastel tag, nav) ===== */
.tw-label {
  font-family: var(--font-sans);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.sidebar-surface .tw-label {
  font-family: inherit;
  text-transform: none;
  letter-spacing: 0;
}
.sidebar-surface .nav-row {
  font-size: var(--fs-14);
  font-weight: 500;
}
.sidebar-surface [data-section-header] {
  font-size: var(--fs-12);
  font-weight: 700;
  color: var(--muted-foreground);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.sidebar-surface [data-section-header] > span:first-child {
  width: 7px;
  height: 7px;
  box-shadow: 0 0 0 2px color-mix(in oklab, var(--accent) 25%, transparent);
}

.tw-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: 4px;
  font-family: var(--font-sans);
  font-size: var(--fs-12);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  line-height: 1.5;
  white-space: nowrap;
}
.tw-tag .dot { width: 6px; height: 6px; border-radius: 50%; flex: none; }
.tw-tag-wrap { white-space: normal; line-height: 1.3; text-align: left; height: auto; overflow-wrap: anywhere; }
.tw-tag-person {
  font-family: var(--font-sans);
  text-transform: none;
  letter-spacing: 0;
  font-size: var(--fs-13);
}
.tw-tag-green  { background: var(--tag-green-bg);  color: var(--tag-green-tx); }
.tw-tag-blue   { background: var(--tag-blue-bg);   color: var(--tag-blue-tx); }
.tw-tag-amber  { background: var(--tag-amber-bg);  color: var(--tag-amber-tx); }
.tw-tag-red    { background: var(--tag-red-bg);    color: var(--tag-red-tx); }
.tw-tag-purple { background: var(--tag-purple-bg); color: var(--tag-purple-tx); }
.tw-tag-sky    { background: var(--tag-sky-bg);    color: var(--tag-sky-tx); }
.tw-tag-orange { background: var(--tag-orange-bg); color: var(--tag-orange-tx); }
.tw-tag-pink   { background: var(--tag-pink-bg);   color: var(--tag-pink-tx); }
.tw-tag-gray   { background: var(--tag-gray-bg);   color: var(--tag-gray-tx); }

.nav-active {
  background: var(--sidebar-accent);
  color: var(--sidebar-accent-foreground);
}
.nav-active svg { color: var(--primary); }

/* ===== Chuyển theme light/dark — hiệu ứng vòng tròn thu phóng (View Transitions API) ===== */
::view-transition-old(root),
::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
}
::view-transition-old(root) { z-index: 0; }
::view-transition-new(root) { z-index: 1; }
