/* ============================================================================
 * hrm-ui · SEMANTIC TOKENS  (Layer 2 — meaning-based, đổi theo theme)
 * ----------------------------------------------------------------------------
 * Đổi Light ↔ Dark = chỉ đổi giá trị ở đây. Component KHÔNG được biết theme nào.
 *
 * bg/text/border trỏ vào --neutral-* (không hardcode hex) → đổi neutral ramp
 * (Slate ↔ Gray, xem primitive.css [data-neutral]) tự lan cả Light + Dark.
 *
 * primary-base giữ nguyên cả 2 theme (spec: 1 primary). Các giá trị primary phái
 * sinh dùng color-mix TỪ --primary-base → đổi brand color (set --primary-base) tự
 * lan ra hover/pressed/bg-subtle/border/focus-ring khắp hệ thống.
 * ==========================================================================*/

/* ------------------------------ LIGHT ------------------------------ */
:root {
  color-scheme: light;

  /* Status tint — alias TỰ FLIP theo theme (light mặc định; .dark override bên dưới).
     Component/bridge PHẢI dùng các alias này (không dùng thẳng *-light) để tự bám dark. */
  --success-bg: var(--success-bg-light);   --success-text: var(--success-text-light);   --success-border: var(--success-border-light);
  --warning-bg: var(--warning-bg-light);   --warning-text: var(--warning-text-light);   --warning-border: var(--warning-border-light);
  --feature-bg: var(--feature-bg-light);
  --error-bg: var(--error-bg-light);       --error-text: var(--error-text-light);       --error-border: var(--error-border-light);
  --info-bg: var(--info-bg-light);         --info-text: var(--info-text-light);         --info-border: var(--info-border-light);
  --away-bg: var(--away-bg-light);         --away-text: var(--away-text-light);         --away-border: var(--away-border-light);

  /* Background */
  --bg-app: var(--neutral-50);
  --bg-canvas: var(--neutral-50);
  --bg-surface: var(--neutral-0);
  --bg-surface-subtle: var(--neutral-100);
  --bg-surface-muted: var(--neutral-200);
  --bg-surface-elevated: var(--neutral-0);
  --bg-inverse: var(--neutral-950);

  /* Text */
  --text-strong: var(--neutral-950);
  --text-body: var(--neutral-600);
  --text-sub: var(--neutral-500);
  --text-soft: var(--neutral-400);
  --text-disabled: var(--neutral-300);
  --text-inverse: var(--neutral-0);
  --text-on-primary: #FFFFFF;

  /* Icon — vai trò màu riêng cho biểu tượng (tách khỏi text để chỉnh contrast/độ đậm
   * độc lập). Trỏ vào text/primary nên tự flip Light↔Dark, KHÔNG cần .dark riêng.
   * Kích thước icon = --icon-xs..xl (primitive), KHÁC cụm màu này. */
  --icon-primary: var(--text-strong);      /* icon nổi bật (active, header) */
  --icon-secondary: var(--text-sub);       /* icon thường (nav, phụ) */
  --icon-disabled: var(--text-disabled);   /* icon vô hiệu */
  --icon-accent: var(--primary-base);      /* icon mang màu brand */
  --icon-on-primary: var(--text-on-primary); /* icon trên nền solid primary */

  /* Border / stroke */
  --border-strong: var(--neutral-300);
  --border-sub: var(--neutral-200);
  --border-soft: var(--neutral-100);
  --border-focus: var(--primary-base);

  /* Primary (derived từ --primary-base) */
  --primary-hover: color-mix(in oklab, var(--primary-base) 88%, black);
  --primary-pressed: color-mix(in oklab, var(--primary-base) 76%, black);
  --primary-bg-subtle: color-mix(in srgb, var(--primary-base) 10%, transparent);
  --primary-bg-soft: color-mix(in srgb, var(--primary-base) 16%, transparent);
  --primary-border: color-mix(in srgb, var(--primary-base) 24%, transparent);
  --primary-focus-ring: color-mix(in srgb, var(--primary-base) 24%, transparent);

  /* State base (giống nhau 2 theme; phân bổ từ hue ramp ở primitive.css) */
  --success-base: var(--green-600);
  --error-base: var(--red-600);
  --warning-base: var(--amber-600);
  --info-base: var(--blue-600);

  /* Faded / neutral */
  --faded-base: var(--text-sub);
  --faded-bg: var(--bg-surface-subtle);
  --faded-border: var(--border-sub);

  /* Overlay */
  --overlay: rgb(14 18 27 / 0.32);

  /* Semantic border roles */
  --border-default: var(--border-sub);
  --border-muted: var(--border-soft);
  --border-hover: var(--border-strong);
  --border-active: var(--primary-base);
  --border-error: var(--error-base);
  --border-success: var(--success-base);

  /* Border chức năng — WCAG 1.4.11 (≥3:1) cho control nhận diện CHỈ bằng viền
   * (checkbox/radio/switch/input-hover). neutral-500 = 4.49:1 (Slate) / 4.23 (Gray). */
  --border-input: var(--neutral-500);
  --border-emphasized: var(--neutral-400);

  /* Overlay state + skeleton/track + selection */
  --overlay-hover: var(--neutral-alpha-10);
  --overlay-pressed: var(--neutral-alpha-16);
  --skeleton: var(--neutral-200);
  --track: var(--neutral-200);
  --selection-bg: var(--primary-bg-soft);

  /* State away (semantic) */
  --away-base: #EAB308;

  /* Tag hues — bg/border = alpha (bám mọi nền), text theo theme. */
  --tag-gray-bg:   color-mix(in srgb, var(--hue-gray-base) 12%, transparent);
  --tag-gray-border: color-mix(in srgb, var(--hue-gray-base) 28%, transparent);
  --tag-gray-text: var(--hue-gray-fg-light);
  --tag-blue-bg:   color-mix(in srgb, var(--hue-blue-base) 12%, transparent);
  --tag-blue-border: color-mix(in srgb, var(--hue-blue-base) 28%, transparent);
  --tag-blue-text: var(--hue-blue-fg-light);
  --tag-cyan-bg:   color-mix(in srgb, var(--hue-cyan-base) 12%, transparent);
  --tag-cyan-border: color-mix(in srgb, var(--hue-cyan-base) 28%, transparent);
  --tag-cyan-text: var(--hue-cyan-fg-light);
  --tag-green-bg:  color-mix(in srgb, var(--hue-green-base) 12%, transparent);
  --tag-green-border: color-mix(in srgb, var(--hue-green-base) 28%, transparent);
  --tag-green-text: var(--hue-green-fg-light);
  --tag-yellow-bg: color-mix(in srgb, var(--hue-yellow-base) 12%, transparent);
  --tag-yellow-border: color-mix(in srgb, var(--hue-yellow-base) 28%, transparent);
  --tag-yellow-text: var(--hue-yellow-fg-light);
  --tag-orange-bg: color-mix(in srgb, var(--hue-orange-base) 12%, transparent);
  --tag-orange-border: color-mix(in srgb, var(--hue-orange-base) 28%, transparent);
  --tag-orange-text: var(--hue-orange-fg-light);
  --tag-red-bg:    color-mix(in srgb, var(--hue-red-base) 12%, transparent);
  --tag-red-border: color-mix(in srgb, var(--hue-red-base) 28%, transparent);
  --tag-red-text:  var(--hue-red-fg-light);
  --tag-pink-bg:   color-mix(in srgb, var(--hue-pink-base) 12%, transparent);
  --tag-pink-border: color-mix(in srgb, var(--hue-pink-base) 28%, transparent);
  --tag-pink-text: var(--hue-pink-fg-light);
  --tag-purple-bg: color-mix(in srgb, var(--hue-purple-base) 12%, transparent);
  --tag-purple-border: color-mix(in srgb, var(--hue-purple-base) 28%, transparent);
  --tag-purple-text: var(--hue-purple-fg-light);
  --tag-teal-bg:   color-mix(in srgb, var(--hue-teal-base) 12%, transparent);
  --tag-teal-border: color-mix(in srgb, var(--hue-teal-base) 28%, transparent);
  --tag-teal-text: var(--hue-teal-fg-light);
}

/* ------------------------------- DARK ------------------------------- */
/* Dark KHÔNG phải light đảo ngược — map step neutral riêng. */
.dark {
  color-scheme: dark;

  /* Status tint — flip sang biến -dark (nền trong hơn, chữ sáng đủ contrast trên nền tối). */
  --success-bg: var(--success-bg-dark);   --success-text: var(--success-text-dark);   --success-border: var(--success-border-dark);
  --warning-bg: var(--warning-bg-dark);   --warning-text: var(--warning-text-dark);   --warning-border: var(--warning-border-dark);
  --feature-bg: var(--feature-bg-dark);
  --error-bg: var(--error-bg-dark);       --error-text: var(--error-text-dark);       --error-border: var(--error-border-dark);
  --info-bg: var(--info-bg-dark);         --info-text: var(--info-text-dark);         --info-border: var(--info-border-dark);
  --away-bg: var(--away-bg-dark);         --away-text: var(--away-text-dark);         --away-border: var(--away-border-dark);

  /* Background */
  --bg-app: var(--neutral-950);
  --bg-canvas: var(--neutral-950);
  --bg-surface: var(--neutral-900);
  --bg-surface-subtle: var(--neutral-800);
  --bg-surface-muted: var(--neutral-700);
  --bg-surface-elevated: var(--neutral-800);
  --bg-inverse: var(--neutral-0);

  /* Text */
  --text-strong: var(--neutral-0);
  --text-body: var(--neutral-300);
  --text-sub: var(--neutral-400);
  --text-soft: var(--neutral-500);
  --text-disabled: var(--neutral-600);
  --text-inverse: var(--neutral-950);
  --text-on-primary: #FFFFFF;

  /* Border / stroke */
  --border-strong: var(--neutral-600);
  --border-sub: var(--neutral-700);
  --border-soft: var(--neutral-800);
  --border-focus: var(--primary-base);

  /* Primary (derived — mix white ở dark) */
  --primary-hover: color-mix(in oklab, var(--primary-base) 88%, white);
  --primary-pressed: color-mix(in oklab, var(--primary-base) 76%, white);
  --primary-bg-subtle: color-mix(in srgb, var(--primary-base) 16%, transparent);
  --primary-bg-soft: color-mix(in srgb, var(--primary-base) 24%, transparent);
  --primary-border: color-mix(in srgb, var(--primary-base) 32%, transparent);
  --primary-focus-ring: color-mix(in srgb, var(--primary-base) 32%, transparent);

  /* Overlay */
  --overlay: rgb(0 0 0 / 0.56);

  /* Shadow override — dark dựa vào border nhiều hơn shadow */
  --shadow-regular-xs: 0 1px 2px rgb(0 0 0 / 0.32);
  --shadow-regular-sm: 0 2px 4px rgb(0 0 0 / 0.36);
  --shadow-regular-md: 0 8px 24px rgb(0 0 0 / 0.40);
  --shadow-regular-lg: 0 16px 40px rgb(0 0 0 / 0.48);

  /* Border chức năng — neutral-500 = 3.82:1 trên surface-900 (≥3:1 ok) */
  --border-input: var(--neutral-500);
  --border-emphasized: var(--neutral-600);

  /* Overlay state (dark = tăng sáng) + skeleton/track */
  --overlay-hover: rgb(255 255 255 / 0.06);
  --overlay-pressed: rgb(255 255 255 / 0.10);
  --skeleton: var(--neutral-800);
  --track: var(--neutral-700);

  /* Tag hues — bg đậm hơn + text sáng (fg-dark) cho nền tối */
  --tag-gray-bg:   color-mix(in srgb, var(--hue-gray-base) 22%, transparent);   --tag-gray-text:   var(--hue-gray-fg-dark);
  --tag-blue-bg:   color-mix(in srgb, var(--hue-blue-base) 22%, transparent);   --tag-blue-text:   var(--hue-blue-fg-dark);
  --tag-cyan-bg:   color-mix(in srgb, var(--hue-cyan-base) 22%, transparent);   --tag-cyan-text:   var(--hue-cyan-fg-dark);
  --tag-green-bg:  color-mix(in srgb, var(--hue-green-base) 22%, transparent);  --tag-green-text:  var(--hue-green-fg-dark);
  --tag-yellow-bg: color-mix(in srgb, var(--hue-yellow-base) 22%, transparent); --tag-yellow-text: var(--hue-yellow-fg-dark);
  --tag-orange-bg: color-mix(in srgb, var(--hue-orange-base) 22%, transparent); --tag-orange-text: var(--hue-orange-fg-dark);
  --tag-red-bg:    color-mix(in srgb, var(--hue-red-base) 22%, transparent);    --tag-red-text:    var(--hue-red-fg-dark);
  --tag-pink-bg:   color-mix(in srgb, var(--hue-pink-base) 22%, transparent);   --tag-pink-text:   var(--hue-pink-fg-dark);
  --tag-purple-bg: color-mix(in srgb, var(--hue-purple-base) 22%, transparent); --tag-purple-text: var(--hue-purple-fg-dark);
  --tag-teal-bg:   color-mix(in srgb, var(--hue-teal-base) 22%, transparent);   --tag-teal-text:   var(--hue-teal-fg-dark);
}
